-- The typed views of this tree's telemetry, for the bc-telemetry layout on PostgreSQL.
--
-- Generated by bc-telemetry-gen. Do not edit.
-- Apply it after the layout, and again whenever the definitions change: it drops every view
-- in the `telemetry` schema and creates this tree's, in one transaction. A view reads its
-- item's rows at its module's current schema_version.

BEGIN;

DO $$
DECLARE
    existing record;
BEGIN
    FOR existing IN SELECT viewname FROM pg_views WHERE schemaname = 'telemetry' LOOP
        EXECUTE format('DROP VIEW telemetry.%I', existing.viewname);
    END LOOP;
END;
$$;

CREATE VIEW telemetry."metric__ledger__entries_posted" AS
SELECT time,
       service_name,
       organization,
       customer,
       trace_id,
       span_id,
       value
FROM telemetry.metrics
WHERE module = 'ledger' AND name = 'entries_posted' AND schema_version = 1;

CREATE VIEW telemetry."log__ledger__entry_posted" AS
SELECT time,
       service_name,
       organization,
       customer,
       trace_id,
       span_id,
       severity,
       body,
       (attributes->>'account')::text AS "account"
FROM telemetry.logs
WHERE module = 'ledger' AND name = 'entry_posted' AND schema_version = 1;

CREATE VIEW telemetry."span__payments__authorize" AS
SELECT time,
       service_name,
       organization,
       customer,
       trace_id,
       span_id,
       end_time,
       (extract(epoch FROM (end_time - time)) * 1000)::double precision AS duration_ms,
       kind,
       status,
       status_message,
       (attributes->>'processor')::text AS "processor"
FROM telemetry.spans
WHERE module = 'payments' AND name = 'authorize' AND schema_version = 1;

